Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, popcnt[MAX_SIZE], DP[MAX_SIZE];
int buffer1[20][MAX_SIZE], buffer2[20][MAX_SIZE], buffer3[20][MAX_SIZE];
long long MOD_SQUARED;
long long temp[20][MAX_SIZE];
long long factorial[MAX_SIZE], inv_factorial[MAX_SIZE];

long long power_mod(long long base, long long exponent) {
    long long result = 1;
    base %= MOD;
    while (exponent) {
        if (exponent & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return result;
}

void setup() {
    factorial[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        factorial[i] = factorial[i-1] * i % MOD;
    inv_factorial[MAX_VAL] = power_mod(factorial[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        inv_factorial[i] = inv_factorial[i+1] * (i+1) % MOD;
}

int next_power_of_two(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fast_walsh_hadamard(int *data, int length, bool inverse = false) {
    static long long temp_array[MAX_SIZE];
    for (int i = 0; i < length; ++i) temp_array[i] = data[i];

    if (inverse) {
        for (int step = 1; step < length; step <<= 1) {
            for (int i = 0; i < length; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long a = temp_array[i + j];
                    long long b = temp_array[i + j + step];
                    temp_array[i + j + step] = (a - b) % MOD;
                }
            }
        }
    } else {
        for (int step = 1; step < length; step <<= 1) {
            for (int i = 0; i < length; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long a = temp_array[i + j];
                    long long b = temp_array[i + j + step];
                    temp_array[i + j + step] = (a + b) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < length; ++i) {
        data[i] = (int)(temp_array[i] % MOD);
        if (data[i] < 0) data[i] += MOD;
    }
}

inline void reduce_mod(long long &x) {
    if (x >= MOD_SQUARED) x -= MOD_SQUARED;
}

void transform_multiply() {
    for (int i = 0; i <= 19; ++i) {
        memset(buffer1[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(temp[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        buffer1[popcnt[i]][i] = DP[i];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_hadamard(buffer1[i], MAX_VAL + 1);

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= MAX_VAL; ++s)
                reduce_mod(temp[q + l][s] += 1LL * buffer1[q][s] * buffer2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= MAX_VAL; ++s)
            buffer3[q][s] = (int)(temp[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fast_walsh_hadamard(buffer3[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        DP[i] = buffer3[popcnt[i]][i];
}

void transform_square() {
    static int temp_buffer[20][MAX_SIZE];
    for (int i = 0; i <= 19; ++i)
        memset(temp[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= MAX_VAL; ++s)
                reduce_mod(temp[q + l][s] += 1LL * buffer2[q][s] * buffer2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= MAX_VAL; ++s)
            temp_buffer[q][s] = (int)(temp[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fast_walsh_hadamard(temp_buffer[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(buffer2[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int i = 0; i <= MAX_VAL; ++i)
        buffer2[popcnt[i]][i] = temp_buffer[popcnt[i]][i];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_hadamard(buffer2[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQUARED = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", power_mod(K, N));
        return 0;
    }

    DP[0] = 1;
    MAX_VAL = next_power_of_two(N + 1) - 1;
    setup();

    for (int i = 0; i <= MAX_VAL; ++i)
        popcnt[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        buffer2[popcnt[i]][i] = inv_factorial[i];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_hadamard(buffer2[i], MAX_VAL + 1);

    int original_K = K;
    while (K) {
        if (K & 1) transform_multiply();
        K >>= 1;
        if (K) transform_square();
    }

    printf("%lld", (power_mod(original_K, N) - factorial[N] * DP[N] % MOD + MOD) % MOD);
    return 0;
}
